begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
insert into auth.users(id) select ('60000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('70000000-0000-0000-0000-00000000000'||n)::uuid,('60000000-0000-0000-0000-00000000000'||n)::uuid,now(),now() from generate_series(1,3) n;
insert into public.employees(id,employee_code,display_name,role) select ('80000000-0000-0000-0000-00000000000'||n)::uuid,'FILE'||n,'Synthetic','employee' from generate_series(1,3) n;
insert into private.employee_auth(employee_id,auth_user_id) select ('80000000-0000-0000-0000-00000000000'||n)::uuid,('60000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,3) n;
insert into public.employee_permissions(employee_id,cases_read,cases_write) values ('80000000-0000-0000-0000-000000000001',false,true),('80000000-0000-0000-0000-000000000002',true,false);
insert into public.families(id,name) values ('90000000-0000-0000-0000-000000000001','وهمي');
insert into public.cases(id,family_id) values ('90000000-0000-0000-0000-000000000002','90000000-0000-0000-0000-000000000001');
select ok((select not public from storage.buckets where id='case-files'),'bucket is private');
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000001","session_id":"70000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id) values ('case-files','90000000-0000-0000-0000-000000000002/90000000-0000-0000-0000-000000000003','60000000-0000-0000-0000-000000000001')$$,'writer uploads object');
select lives_ok($$insert into public.case_files(case_id,storage_path,file_name,mime_type,size_bytes,uploaded_by) values ('90000000-0000-0000-0000-000000000002','90000000-0000-0000-0000-000000000002/90000000-0000-0000-0000-000000000003','synthetic.png','image/png',5,'60000000-0000-0000-0000-000000000001')$$,'writer creates metadata');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('case-files','90000000-0000-0000-0000-000000000099/90000000-0000-0000-0000-000000000003')$$,'42501',null,'unknown case denied');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000002","session_id":"70000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.case_files),1,'reader sees metadata');
select is((select count(*)::int from storage.objects where bucket_id='case-files'),1,'reader sees object');
select throws_ok($$insert into storage.objects(bucket_id,name) values ('case-files','90000000-0000-0000-0000-000000000002/90000000-0000-0000-0000-000000000004')$$,'42501',null,'reader cannot upload');
reset role;
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000003","session_id":"70000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.case_files),0,'unprivileged cannot see metadata');
select is((select count(*)::int from storage.objects where bucket_id='case-files'),0,'unprivileged cannot see object');
reset role;
delete from auth.sessions where id='70000000-0000-0000-0000-000000000002';
select set_config('request.jwt.claims','{"sub":"60000000-0000-0000-0000-000000000002","session_id":"70000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from storage.objects where bucket_id='case-files'),0,'expired session cannot see object');
select * from finish(); rollback;
